import base64
import sqlite3
import zipfile
from io import BytesIO
from pathlib import Path

from Crypto.Cipher import AES
from Crypto.Util.Padding import unpad

# ---------- CONFIG ----------
BASE_DIR = Path(__file__).resolve().parent
DB_PATH = BASE_DIR / "app.sqlite3"
OUTPUT_FOLDER = BASE_DIR / "extracted_photos"
# Must match hide_photo.py (16, 24, or 32 bytes)
PASSWORD = b"SixteenByteKey!!"
DUMMY_TITLE = "System Configuration Backup"
DUMMY_INTRO = (
    "This is an auto-generated configuration snapshot. "
    "Do not modify manually.\n\n"
)
# ----------------------------

if len(PASSWORD) not in (16, 24, 32):
    raise ValueError(
        f"PASSWORD must be 16, 24, or 32 bytes (got {len(PASSWORD)})"
    )

if not DB_PATH.is_file():
    raise FileNotFoundError(f"Database not found: {DB_PATH}")

conn = sqlite3.connect(DB_PATH)
cursor = conn.cursor()

cursor.execute(
    """
    SELECT content FROM system_config
    WHERE title = ?
    ORDER BY date_posted DESC, id DESC
    LIMIT 1
    """,
    (DUMMY_TITLE,),
)
row = cursor.fetchone()
conn.close()

if not row:
    raise RuntimeError(
        f"Hidden data not found in {DB_PATH.name} "
        f"(table system_config, title={DUMMY_TITLE!r})."
    )

full_content = row[0]
if full_content.startswith(DUMMY_INTRO):
    b64_part = full_content[len(DUMMY_INTRO) :]
else:
    b64_part = full_content

encrypted = base64.b64decode(b64_part)
iv = encrypted[:16]
ct = encrypted[16:]

cipher = AES.new(PASSWORD, AES.MODE_CBC, iv=iv)
decrypted = unpad(cipher.decrypt(ct), AES.block_size)

OUTPUT_FOLDER.mkdir(parents=True, exist_ok=True)
with zipfile.ZipFile(BytesIO(decrypted)) as zf:
    names = zf.namelist()
    zf.extractall(OUTPUT_FOLDER)

print(f"Extracted {len(names)} photos to '{OUTPUT_FOLDER.name}':")
for name in names:
    print(f"  - {name}")
